use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: FxIndexMap ; use rustc_middle :: mir :: * ; use rustc_middle :: ty :: Ty ; use rustc_span :: Span ; use tracing :: debug ; use crate :: builder :: Builder ; use crate :: builder :: expr :: as_place :: PlaceBase ; use crate :: builder :: matches :: { Binding , Candidate , FlatPat , MatchPairTree , TestCase } ; impl < 'a , 'tcx > Builder < 'a , 'tcx > { #[doc = " Creates a false edge to `imaginary_target` and a real edge to"] #[doc = " real_target. If `imaginary_target` is none, or is the same as the real"] #[doc = " target, a Goto is generated instead to simplify the generated MIR."] pub (crate) fn false_edges (& mut self , from_block : BasicBlock , real_target : BasicBlock , imaginary_target : BasicBlock , source_info : SourceInfo ,) { if imaginary_target != real_target { self . cfg . terminate (from_block , source_info , TerminatorKind :: FalseEdge { real_target , imaginary_target } ,) ; } else { self . cfg . goto (from_block , source_info , real_target) } } } #[doc = " Determine the set of places that have to be stable across match guards."] #[doc = ""] #[doc = " Returns a list of places that need a fake borrow along with a local to store it."] #[doc = ""] #[doc = " Match exhaustiveness checking is not able to handle the case where the place being matched on is"] #[doc = " mutated in the guards. We add \"fake borrows\" to the guards that prevent any mutation of the"] #[doc = " place being matched. There are a some subtleties:"] #[doc = ""] #[doc = " 1. Borrowing `*x` doesn't prevent assigning to `x`. If `x` is a shared reference, the borrow"] #[doc = "    isn't even tracked. As such we have to add fake borrows of any prefixes of a place."] #[doc = " 2. We don't want `match x { (Some(_), _) => (), .. }` to conflict with mutable borrows of `x.1`, so we"] #[doc = "    only add fake borrows for places which are bound or tested by the match."] #[doc = " 3. We don't want `match x { Some(_) => (), .. }` to conflict with mutable borrows of `(x as"] #[doc = "    Some).0`, so the borrows are a special shallow borrow that only affects the place and not its"] #[doc = "    projections."] #[doc = "    ```rust"] #[doc = "    let mut x = (Some(0), true);"] #[doc = "    match x {"] #[doc = "        (Some(_), false) => {}"] #[doc = "        _ if { if let Some(ref mut y) = x.0 { *y += 1 }; true } => {}"] #[doc = "        _ => {}"] #[doc = "    }"] #[doc = "    ```"] #[doc = " 4. The fake borrows may be of places in inactive variants, e.g. here we need to fake borrow `x`"] #[doc = "    and `(x as Some).0`, but when we reach the guard `x` may not be `Some`."] #[doc = "    ```rust"] #[doc = "    let mut x = (Some(Some(0)), true);"] #[doc = "    match x {"] #[doc = "        (Some(Some(_)), false) => {}"] #[doc = "        _ if { if let Some(Some(ref mut y)) = x.0 { *y += 1 }; true } => {}"] #[doc = "        _ => {}"] #[doc = "    }"] #[doc = "    ```"] #[doc = "    So it would be UB to generate code for the fake borrows. They therefore have to be removed by"] #[doc = "    a MIR pass run after borrow checking."] pub (super) fn collect_fake_borrows < 'tcx > (cx : & mut Builder < '_ , 'tcx > , candidates : & [Candidate < 'tcx >] , temp_span : Span , scrutinee_base : PlaceBase ,) -> Vec < (Place < 'tcx > , Local , FakeBorrowKind) > { if candidates . iter () . all (| candidate | ! candidate . has_guard) { return Vec :: new () ; } let mut collector = FakeBorrowCollector { cx , scrutinee_base , fake_borrows : FxIndexMap :: default () } ; for candidate in candidates . iter () { collector . visit_candidate (candidate) ; } let fake_borrows = collector . fake_borrows ; debug ! ("add_fake_borrows fake_borrows = {:?}" , fake_borrows) ; let tcx = cx . tcx ; fake_borrows . iter () . map (| (matched_place , borrow_kind) | { let fake_borrow_deref_ty = matched_place . ty (& cx . local_decls , tcx) . ty ; let fake_borrow_ty = Ty :: new_imm_ref (tcx , tcx . lifetimes . re_erased , fake_borrow_deref_ty) ; let mut fake_borrow_temp = LocalDecl :: new (fake_borrow_ty , temp_span) ; fake_borrow_temp . local_info = ClearCrossCrate :: Set (Box :: new (LocalInfo :: FakeBorrow)) ; let fake_borrow_temp = cx . local_decls . push (fake_borrow_temp) ; (* matched_place , fake_borrow_temp , * borrow_kind) }) . collect () } pub (super) struct FakeBorrowCollector < 'a , 'b , 'tcx > { cx : & 'a mut Builder < 'b , 'tcx > , #[doc = " Base of the scrutinee place. Used to distinguish bindings inside the scrutinee place from"] #[doc = " bindings inside deref patterns."] scrutinee_base : PlaceBase , #[doc = " Store for each place the kind of borrow to take. In case of conflicts, we take the strongest"] #[doc = " borrow (i.e. Deep > Shallow)."] #[doc = " Invariant: for any place in `fake_borrows`, all the prefixes of this place that are"] #[doc = " dereferences are also borrowed with the same of stronger borrow kind."] fake_borrows : FxIndexMap < Place < 'tcx > , FakeBorrowKind > , } impl < 'a , 'b , 'tcx > FakeBorrowCollector < 'a , 'b , 'tcx > { fn fake_borrow (& mut self , place : Place < 'tcx > , kind : FakeBorrowKind) { if self . fake_borrows . get (& place) . is_some_and (| k | * k >= kind) { return ; } self . fake_borrows . insert (place , kind) ; self . fake_borrow_deref_prefixes (place , kind) ; } fn fake_borrow_deref_prefixes (& mut self , place : Place < 'tcx > , kind : FakeBorrowKind) { for (place_ref , elem) in place . as_ref () . iter_projections () . rev () { if let ProjectionElem :: Deref = elem { let place = place_ref . to_place (self . cx . tcx) ; if self . fake_borrows . get (& place) . is_some_and (| k | * k >= kind) { return ; } self . fake_borrows . insert (place , kind) ; } } } fn visit_candidate (& mut self , candidate : & Candidate < 'tcx >) { for binding in & candidate . extra_data . bindings { if let super :: SubpatternBindings :: One (binding) = binding { self . visit_binding (binding) ; } } for match_pair in & candidate . match_pairs { self . visit_match_pair (match_pair) ; } } fn visit_flat_pat (& mut self , flat_pat : & FlatPat < 'tcx >) { for binding in & flat_pat . extra_data . bindings { if let super :: SubpatternBindings :: One (binding) = binding { self . visit_binding (binding) ; } } for match_pair in & flat_pat . match_pairs { self . visit_match_pair (match_pair) ; } } fn visit_match_pair (& mut self , match_pair : & MatchPairTree < 'tcx >) { if let TestCase :: Or { pats , .. } = & match_pair . test_case { for flat_pat in pats . iter () { self . visit_flat_pat (flat_pat) } } else if matches ! (match_pair . test_case , TestCase :: Deref { .. }) { if let Some (place) = match_pair . place { self . fake_borrow (place , FakeBorrowKind :: Deep) ; } } else { if let Some (place) = match_pair . place { self . fake_borrow (place , FakeBorrowKind :: Shallow) ; } for subpair in & match_pair . subpairs { self . visit_match_pair (subpair) ; } } } fn visit_binding (& mut self , Binding { source , .. } : & Binding < 'tcx >) { if let PlaceBase :: Local (l) = self . scrutinee_base && l != source . local { return ; } self . fake_borrow_deref_prefixes (* source , FakeBorrowKind :: Shallow) ; } } #[must_use] pub (crate) fn ref_pat_borrow_kind (ref_mutability : Mutability) -> BorrowKind { match ref_mutability { Mutability :: Mut => BorrowKind :: Mut { kind : MutBorrowKind :: Default } , Mutability :: Not => BorrowKind :: Shared , } }